#!/usr/bin/env node
/**
 * Reads .ghl-book-products.json (written by seed-book-products.mjs) and
 * generates src/lib/book-checkouts.ts — a typed map from book slug to its
 * GHL checkout URL + price. The BooksSection on the marketing site imports
 * that map and uses it to render each cover as a real "Buy / Pre-Order"
 * link instead of the placeholder "Learn More" CTA.
 *
 * Usage:
 *   node scripts/wire-book-products.mjs
 *
 * Re-runnable. Overwrites the generated file each time. Commit the result
 * (it's NOT gitignored — that's the whole point: it ships to production).
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const INPUT_PATH = ".ghl-book-products.json";
const OUTPUT_PATH = resolve("src/lib/book-checkouts.ts");

if (!existsSync(INPUT_PATH)) {
  console.error(`\n${INPUT_PATH} not found. Run scripts/seed-book-products.mjs first.\n`);
  process.exit(1);
}

const raw = JSON.parse(readFileSync(INPUT_PATH, "utf8"));
if (!Array.isArray(raw) || raw.length === 0) {
  console.error(`\n${INPUT_PATH} is empty or invalid.\n`);
  process.exit(1);
}

const wired = raw
  .filter((e) => e.slug && e.checkoutUrl)
  .map((e) => ({
    slug: String(e.slug),
    title: String(e.title ?? ""),
    price: Number(e.price ?? 0),
    productId: String(e.productId ?? ""),
    priceId: String(e.priceId ?? ""),
    url: String(e.checkoutUrl),
  }));

if (wired.length === 0) {
  console.error("\nNo entries have both slug and checkoutUrl set.");
  console.error("Either re-run seed-book-products.mjs with GHL_STORE_BASE set,");
  console.error("or paste per-book checkoutUrl values into .ghl-book-products.json by hand.\n");
  process.exit(1);
}

const body = `/**
 * Generated by scripts/wire-book-products.mjs from .ghl-book-products.json.
 * Do not edit by hand — re-run the wire script after re-seeding GHL.
 *
 * The BooksSection on the homepage imports BOOK_CHECKOUTS to turn each
 * book cover into a working checkout link.
 */

export type BookCheckout = {
  /** Slug shared with BOOKS in portfolio-data.ts. */
  slug: string;
  /** Display title (kept here for sanity / cross-checking). */
  title: string;
  /** USD list price as set in GHL. */
  price: number;
  /** GHL product id — useful for analytics or follow-up automations. */
  productId: string;
  /** GHL price id. */
  priceId: string;
  /** Public checkout / pre-order URL the buyer opens. */
  url: string;
};

export const BOOK_CHECKOUTS: Record<string, BookCheckout> = {
${wired
  .map(
    (b) =>
      `  ${JSON.stringify(b.slug)}: {\n` +
      `    slug: ${JSON.stringify(b.slug)},\n` +
      `    title: ${JSON.stringify(b.title)},\n` +
      `    price: ${b.price},\n` +
      `    productId: ${JSON.stringify(b.productId)},\n` +
      `    priceId: ${JSON.stringify(b.priceId)},\n` +
      `    url: ${JSON.stringify(b.url)},\n` +
      `  },`,
  )
  .join("\n")}
};
`;

writeFileSync(OUTPUT_PATH, body);
console.log(`\n✓ Wrote ${wired.length} book checkouts → ${OUTPUT_PATH}`);
console.log("Commit and push to ship the live links to the website.\n");
